using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Globalization;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace MLInferenceServer
{
    public class ModelEndpointRegistry
    {
        private readonly ConcurrentDictionary<string, string> _endpoints = new();
        private readonly ConcurrentDictionary<string, HttpClient> _pool = new();

        public ModelEndpointRegistry()
        {
            _endpoints["production-model"] = "https://ml-prod.internal.corp:8443/v1/predict";
            _endpoints["staging-model"] = "https://ml-staging.internal.corp:8443/v1/predict";
            _endpoints["canary-model"] = "https://ml-canary.internal.corp:8443/v1/predict";
        }

        public string ResolveEndpoint(string modelName) =>
            _endpoints.TryGetValue(modelName, out var ep) ? ep : null;

        public HttpClient GetOrCreateClient(string endpoint)
        {
            return _pool.GetOrAdd(endpoint, url => new HttpClient
            {
                BaseAddress = new Uri(url),
                Timeout = TimeSpan.FromSeconds(30)
            });
        }

        public bool RegisterEndpoint(string modelName, string url)
        {
            if (!IsValidModelName(modelName)) return false;
            if (!IsValidEndpointUrl(url)) return false;
            _endpoints[modelName] = url;
            return true;
        }

        private bool IsValidModelName(string name)
        {
            if (string.IsNullOrWhiteSpace(name) || name.Length > 64) return false;
            foreach (char c in name)
            {
                if (!char.IsLetterOrDigit(c) && c != '-' && c != '_') return false;
            }
            return true;
        }

        private bool IsValidEndpointUrl(string url)
        {
            if (!Uri.TryCreate(url, UriKind.Absolute, out var uri)) return false;
            if (uri.Scheme != "https") return false;
            if (!IsAllowedHost(uri.Host)) return false;
            return true;
        }

        private bool IsAllowedHost(string host)
        {
            string normalizedHost = NormalizeHostname(host);
            string[] allowedSuffixes = { ".internal.corp", ".ml-cluster.corp" };
            foreach (var suffix in allowedSuffixes)
            {
                if (normalizedHost.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }

        private string NormalizeHostname(string host)
        {
            // Normalize Unicode characters in hostname using strict IDNA rules
            // Convert to ASCII punycode and validate strictly
            try
            {
                var idn = new IdnMapping { AllowUnassigned = false, UseStd3AsciiRules = true };
                string ascii = idn.GetAscii(host);
                // Verify the ASCII form only contains valid DNS characters
                foreach (char c in ascii)
                {
                    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
                          (c >= '0' && c <= '9') || c == '-' || c == '.'))
                        return "";
                }
                return ascii.ToLowerInvariant();
            }
            catch
            {
                return "";
            }
        }
    }

    public class InferenceRequest
    {
        public string ModelName { get; set; }
        public float[] Features { get; set; }
        public Dictionary<string, string> Metadata { get; set; }
    }

    public class InferenceService
    {
        private readonly ModelEndpointRegistry _registry;

        public InferenceService(ModelEndpointRegistry registry)
        {
            _registry = registry;
        }

        public async Task<string> RunInference(InferenceRequest request)
        {
            var endpoint = _registry.ResolveEndpoint(request.ModelName);
            if (endpoint == null)
                return "{\"error\": \"Model not found\"}";

            var client = _registry.GetOrCreateClient(endpoint);
            var payload = System.Text.Json.JsonSerializer.Serialize(new
            {
                features = request.Features,
                metadata = request.Metadata
            });

            var content = new StringContent(payload, Encoding.UTF8, "application/json");
            var response = await client.PostAsync("/v1/predict", content);
            return await response.Content.ReadAsStringAsync();
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddSingleton<ModelEndpointRegistry>();
            builder.Services.AddScoped<InferenceService>();
            var app = builder.Build();

            app.MapPost("/api/inference", async (InferenceRequest req, InferenceService svc) =>
            {
                var result = await svc.RunInference(req);
                return Results.Content(result, "application/json");
            });

            app.MapPost("/api/admin/register-model", (HttpContext ctx, ModelEndpointRegistry registry) =>
            {
                var adminKey = ctx.Request.Headers["X-Admin-Key"].ToString();
                if (string.IsNullOrEmpty(adminKey) ||
                    !CryptographicOperations.FixedTimeEquals(
                        Encoding.UTF8.GetBytes(adminKey),
                        Encoding.UTF8.GetBytes(Environment.GetEnvironmentVariable("ADMIN_SECRET_KEY") ?? "")))
                    return Results.Unauthorized();

                var modelName = ctx.Request.Query["name"].ToString();
                var url = ctx.Request.Query["url"].ToString();

                if (registry.RegisterEndpoint(modelName, url))
                    return Results.Ok(new { registered = true, model = modelName });
                return Results.BadRequest(new { error = "Invalid model name or URL" });
            });

            app.Run();
        }
    }
}
